/**
 * BADGER coat markings, v1 (frozen). GENERATED by dev/trace/gen_left.py + gen_heads.py + emit_spots.py from
 * traces over the approved sheet crops. Do not add, remove or move markings here by hand:
 * PROJECT_INSTRUCTIONS.md freezes the approved simplified coat pattern.
 *
 * Body spots come from the LEFT coat map (reference/crops/badger_coat_left.png). Each record's `path` is a
 * cubic-bezier path in its PART's local coordinates (origin = that part's pivot, world units, ZOO = 900) for
 * the left-side view, and it is rendered inside that part's group, clipped to the part outline, so it
 * moves with the part and can never slide or jump sides. No randomness anywhere.
 * `ref` is the spot centre in the reference crop (2x sheet pixels) for QA.
 */
export type BadgerPartId =
	| 'torso'
	| 'neck'
	| 'legFrontNear'
	| 'legFrontFar'
	| 'legHindNear'
	| 'legHindFar'
	| 'tail'
	| 'head'
	| 'frontNeck'
	// parts of the front / back / three-quarter views and the sit / lie pose bodies
	| 'legFrontRight'
	| 'legFrontLeft'
	| 'legHindRight'
	| 'legHindLeft'
	| 'haunch'
	| 'pawHindNear';

export type BadgerSpot = {
	readonly id: string;
	/** Anatomical side the marking lives on. */
	readonly side: 'left' | 'right' | 'midline';
	readonly part: BadgerPartId;
	/** Leg segment for leg spots. */
	readonly segment?: 'upper' | 'lower' | 'paw';
	readonly path: string;
	readonly ref: {readonly crop: string; readonly x: number; readonly y: number};
	readonly desc: string;
	/** Id of the same physical marking in another map (e.g. a top-map T- spot that is also a side-map spot). */
	readonly sameAs?: string;
};

